using GaoApp.Web.Services.Assistant;
using GaoApp.Web.Services.CustomerService;
using Microsoft.AspNetCore.DataProtection;
using Xunit;
namespace GaoApp.Tests.Security;
public sealed partial class CustomerChannelStoreTests:IDisposable
{
    private readonly string directory=Path.Combine(Path.GetTempPath(),"GaoChannelTests",Guid.NewGuid().ToString("N"));
    private readonly AssistantIntegrationTests.FixedClock clock=new();
    private readonly AssistantIntegrationTests.Monitor<CustomerServiceOptions> options=new(new(){DatabasePath="channels.db"});
    private readonly CustomerStaff agent=new(1,1,"TEST agent",true,true,true);
    private IDataProtector Protector{get{Directory.CreateDirectory(directory);return DataProtectionProvider.Create(new DirectoryInfo(Path.Combine(directory,"keys"))).CreateProtector("TEST channel identity");}}
    private CustomerServiceStore Store()=>new(new AssistantIntegrationTests.EnvironmentStub(directory),options,clock,protection:Protector);
    private CustomerChannelConnection Connection(string id="facebook-one",int store=1,bool ai=true)=>new(){Id=id,Provider="facebook",AccountId="123456",StoreId=store,Enabled=true,AutoReply=ai};
    private CustomerChannelConnection Zalo(string id="zalo-one",bool ai=true)=>new(){Id=id,Provider="zalomarketing",AccountId=Guid.NewGuid().ToString("D"),StoreId=1,Enabled=true,AutoReply=ai,BaseUrl="https://zalo.test/"};
    private void ReadyZalo(CustomerServiceStore s,CustomerChannelConnection c){s.ChannelState(c);s.ChannelPoll(c,1,true,true);using var db=new Microsoft.Data.Sqlite.SqliteConnection("Data Source="+Path.Combine(directory,"channels.db")+";Pooling=False");db.Open();using var cmd=db.CreateCommand();cmd.CommandText="INSERT INTO CskhZaloSync(Connection,Binding,LastCompleted) VALUES($connection,$binding,$now) ON CONFLICT(Connection) DO UPDATE SET LastCompleted=excluded.LastCompleted";cmd.Parameters.AddWithValue("$connection",c.Id);cmd.Parameters.AddWithValue("$binding",c.Binding);cmd.Parameters.AddWithValue("$now",clock.Now.ToUnixTimeMilliseconds());cmd.ExecuteNonQuery();}
    private CustomerChannelIncoming Input(string id="mid-1",string peer="999111",string text="TEST sữa")=>new(id,peer,text,clock.Now,id);
    private Guid Import(CustomerServiceStore s,CustomerChannelConnection c,CustomerChannelIncoming? input=null){s.Configure(c.StoreId,true,s.Settings(c.StoreId).Version);return s.ImportChannel(c,input??Input())!.Value;}
    private CustomerConversation Reply(CustomerServiceStore s,Guid id,string text="TEST reply"){var row=s.StaffGet(agent,id);if(row.Mode!="human")row=s.StaffCommand(agent,id,new(Guid.NewGuid(),"claim",row.Version));return s.StaffCommand(agent,id,new(Guid.NewGuid(),"reply",row.Version,text));}
    [Fact]public void Duplicate_provider_event_is_durable_and_does_not_duplicate_messages_or_AI(){var s=Store();var c=Connection();var id=Import(s,c);Assert.Null(s.ImportChannel(c,Input()));Assert.Equal(2,s.StaffGet(agent,id).Messages.Length);Assert.NotNull(s.TakeChannelTurn(c));Assert.Null(Store().TakeChannelTurn(c));}
    [Fact]public void Conflicting_event_reuse_rolls_back_and_keeps_original(){var s=Store();var c=Connection();var id=Import(s,c);Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.ImportChannel(c,Input(text:"different"))).Status);Assert.DoesNotContain(s.StaffGet(agent,id).Messages,m=>m.Text=="different");}
    [Fact]public void Peer_connection_and_store_are_distinct_even_when_names_match(){var s=Store();var a=Connection();var first=Import(s,a);var second=Import(s,a,Input("mid-2","999222"));var third=Import(s,Connection("facebook-two",2),Input());Assert.NotEqual(first,second);Assert.NotEqual(first,third);Assert.Equal(404,Assert.Throws<AssistantException>(()=>s.StaffGet(agent,third)).Status);Assert.Equal("facebook",s.StaffGet(agent,first).Source);}
    [Fact]public void Closing_a_thread_starts_a_new_thread_but_replay_still_deduplicates(){var s=Store();var c=Connection();var first=Import(s,c);var row=s.StaffGet(agent,first);s.StaffCommand(agent,first,new(Guid.NewGuid(),"close",row.Version));Assert.Null(s.ImportChannel(c,Input()));Assert.NotEqual(first,s.ImportChannel(c,Input("mid-new")));}
    [Fact]public void Paused_disabled_or_unconfigured_store_never_imports_or_dispatches(){var s=Store();var c=Connection();Assert.Null(s.ImportChannel(c,Input()));var id=Import(s,c);var state=s.ChannelState(c);s.PauseChannel(c,true,state.Version);Assert.Null(s.ImportChannel(c,Input("other")));Assert.Null(s.TakeChannelTurn(c));Reply(s,id);Assert.Null(s.TakeChannelDispatch(c));Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.PauseChannel(c,false,state.Version)).Status);}
    [Fact]public void Reusing_connection_id_for_another_account_is_rejected(){var s=Store();var c=Connection();Import(s,c);var changed=Connection();changed.AccountId="other";Assert.Equal(409,Assert.Throws<AssistantException>(()=>s.ChannelState(changed)).Status);}
    [Theory][InlineData("Gặp nhân viên")][InlineData("đơn hàng của tôi")][InlineData("tôi có bao nhiêu điểm")]
    public void Handoff_and_private_queries_never_open_private_data_or_start_AI(string text){var s=Store();var c=Connection();var id=Import(s,c,Input(text:text));Assert.Equal("waiting",s.StaffGet(agent,id).Mode);Assert.Null(s.TakeChannelTurn(c));Assert.Throws<AssistantException>(()=>s.IssueIdentity(agent,id,new(Guid.NewGuid(),s.StaffGet(agent,id).Version,42,"in_person","TEST verified identity",true),null!));}
    [Fact]public void Attachments_long_text_and_older_events_go_to_human(){var s=Store();var c=Connection();var id=Import(s,c,Input() with{NeedsHuman=true});Assert.Equal("waiting",s.StaffGet(agent,id).Mode);Assert.Null(s.TakeChannelTurn(c));}
    [Fact]public void Late_AI_cannot_reply_after_staff_claims(){var s=Store();var c=Connection();var id=Import(s,c);var turn=s.TakeChannelTurn(c)!;var row=s.StaffGet(agent,id);s.StaffCommand(agent,id,new(Guid.NewGuid(),"claim",row.Version));s.Complete(turn.Who,"LATE AI","{}",null);Assert.Null(s.TakeChannelDispatch(c));Assert.DoesNotContain(s.StaffGet(agent,id).Messages,m=>m.Text=="LATE AI");}
    [Fact]public void AI_outbox_is_cancelled_if_human_takes_over_before_sending(){var s=Store();var c=Connection();var id=Import(s,c);var turn=s.TakeChannelTurn(c)!;s.Complete(turn.Who,"AI reply","{}",null);var row=s.StaffGet(agent,id);s.StaffCommand(agent,id,new(Guid.NewGuid(),"claim",row.Version));Assert.Null(s.TakeChannelDispatch(c));Assert.Equal("cancelled",s.StaffGet(agent,id).Messages.Single(m=>m.Role=="assistant").Delivery!.State);}
    [Fact]public async Task Outbox_claims_are_exclusive_and_unknown_sends_survive_restart_for_review(){var s=Store();var c=Connection(ai:false);var id=Import(s,c);Reply(s,id);var other=Store();var results=await Task.WhenAll(Task.Run(()=>s.TakeChannelDispatch(c)),Task.Run(()=>other.TakeChannelDispatch(c)));Assert.Single(results,r=>r is not null);clock.Now=clock.Now.AddSeconds(121);Assert.Null(Store().TakeChannelDispatch(c));Assert.Equal("review",Store().StaffGet(agent,id).Messages.Single(m=>m.Role=="agent").Delivery!.State);}
    [Fact]public void Accepted_Zalo_job_is_not_reported_sent_and_peer_reference_are_frozen(){var s=Store();var c=Connection(ai:false);var id=Import(s,c);Reply(s,id);var item=s.TakeChannelDispatch(c)!;s.FinishChannelDispatch(item,new("accepted",JobId:Guid.NewGuid().ToString()));Assert.Equal("accepted",s.StaffGet(agent,id).Messages.Single(m=>m.Role=="agent").Delivery!.State);clock.Now=clock.Now.AddSeconds(16);s.ImportChannel(c,Input("newer"));var poll=s.TakeChannelDispatch(c)!;Assert.Equal(item.Peer,poll.Peer);Assert.Equal(item.Reference,poll.Reference);Assert.Equal("accepted",poll.State);}
    [Fact]public void Manager_review_is_explicit_idempotent_and_scoped(){var s=Store();var c=Connection(ai:false);var id=Import(s,c);Reply(s,id);var item=s.TakeChannelDispatch(c)!;s.FinishChannelDispatch(item,new("review",Code:"unknown"));Assert.Throws<AssistantException>(()=>s.ReviewChannelDispatch(agent,c,item.Id,new(Guid.NewGuid(),"retry",false)));var command=new CustomerChannelReview(Guid.NewGuid(),"retry",true);s.ReviewChannelDispatch(agent,c,item.Id,command);s.ReviewChannelDispatch(agent,c,item.Id,command);Assert.NotNull(s.TakeChannelDispatch(c));Assert.Throws<AssistantException>(()=>s.ReviewChannelDispatch(agent with{CanManage=false},c,item.Id,new(Guid.NewGuid(),"discard",false)));}
    [Fact]public void Facebook_cannot_send_outside_response_window(){var s=Store();var c=Connection(ai:false);var id=Import(s,c);Reply(s,id);clock.Now=clock.Now.AddHours(24);var item=s.TakeChannelDispatch(c)!;Assert.Equal("reply_window_expired",s.ChannelDispatchBlock(c,item));}
    [Fact]public void Receipt_only_baseline_never_creates_a_conversation_or_reply(){var s=Store();var c=Connection();s.SeedChannelReceipt(c,Input());Assert.True(Store().ChannelSeen(c,"mid-1"));Assert.Empty(s.Inbox(agent,"all"));}
    [Fact]public void Failing_AI_delivery_queues_staff_and_does_not_keep_generating(){var s=Store();var c=Connection();Import(s,c);var turn=s.TakeChannelTurn(c)!;s.Complete(turn.Who,"AI reply","{}",null);var send=s.TakeChannelDispatch(c)!;s.FinishChannelDispatch(send,new("review",Code:"unknown"));Assert.Equal("waiting",s.StaffGet(agent,turn.Who.ConversationId).Mode);Assert.Null(s.TakeChannelTurn(c));}
    [Fact]public void Handoff_notice_reaches_the_channel_without_a_model_call(){var s=Store();var c=Connection();var id=Import(s,c,Input(text:"Gặp nhân viên"));Assert.Null(s.TakeChannelTurn(c));var notice=s.TakeChannelDispatch(c)!;Assert.Equal("handoff",notice.Kind);Assert.Null(s.ChannelDispatchBlock(c,notice));Assert.Equal("waiting",s.StaffGet(agent,id).Mode);}
    [Fact]public void AI_handoff_reply_is_not_discarded_as_a_late_business_answer(){var s=Store();var c=Connection();Import(s,c);var turn=s.TakeChannelTurn(c)!;s.Complete(turn.Who,"TEST chuyển nhân viên","{}","needs_human");var notice=s.TakeChannelDispatch(c)!;Assert.Equal("handoff",notice.Kind);Assert.Null(s.ChannelDispatchBlock(c,notice));}
    [Fact]public void Full_channel_thread_rolls_over_without_dropping_the_next_message(){options.CurrentValue.MaximumMessagesPerConversation=20;var s=Store();var c=Connection(ai:false);var first=Import(s,c);for(var n=0;n<18;n++)s.ImportChannel(c,Input("mid-"+(n+2),text:"TEST message "+n));var rows=s.Inbox(agent,"all");Assert.Equal(2,rows.Length);Assert.Equal("closed",s.StaffGet(agent,first).Mode);var current=Assert.Single(rows,r=>r.Mode!="closed");Assert.Contains(s.StaffGet(agent,current.Id).Messages,m=>m.Text=="TEST message 17");}
    [Fact]public void Unknown_outcome_blocks_same_peer_even_after_a_new_thread_is_opened(){var s=Store();var c=Connection(ai:false);var first=Import(s,c);Reply(s,first);var item=s.TakeChannelDispatch(c)!;s.FinishChannelDispatch(item,new("review",Code:"unknown"));var old=s.StaffGet(agent,first);s.StaffCommand(agent,first,new(Guid.NewGuid(),"close",old.Version));var next=s.ImportChannel(c,Input("next-thread"))!.Value;Reply(s,next);Assert.Null(s.TakeChannelDispatch(c));s.ReviewChannelDispatch(agent,c,item.Id,new(Guid.NewGuid(),"discard",false));Assert.Equal(next,s.TakeChannelDispatch(c)!.ConversationId);}
    [Fact]public void Zalo_private_queries_are_deterministic_and_dispatch_is_fenced_by_the_verified_grant(){
        var s=Store();var c=Zalo();var id=Import(s,c,Input("zalo-initial",peer:"peer-1",text:"Xin chào"));var row=s.StaffGet(agent,id);row=s.StaffCommand(agent,id,new(Guid.NewGuid(),"claim",row.Version));
        var issue=new CustomerIdentityIssue(Guid.NewGuid(),row.Version,42,"verified_callback","TEST phone callback verified",true);var code=s.IssueIdentity(agent,id,issue,Protector,"PROTECTED_TEST_PHONE");
        Assert.True(s.RedeemIdentity(1,row.VisitorId,id,new(Guid.NewGuid(),code.Code!)));var target=s.RequireChannelIdentityTarget(c,1,row.VisitorId,id);var generation=s.ActiveChannelIdentityGeneration(c,id,target);Assert.NotNull(generation);
        ReadyZalo(s,c);var privateId=s.ImportChannel(c,Input("zalo-private",peer:"peer-1",text:"đơn hàng của tôi"))!.Value;Assert.Equal(id,privateId);Assert.Null(s.TakeChannelTurn(c));
        var turn=s.TakeChannelPrivateTurn(c);Assert.NotNull(turn);s.CompleteChannelPrivateTurn(turn!,"TEST private order result",generation);
        var saved=s.StaffGet(agent,id);Assert.DoesNotContain(saved.Messages,m=>m.Text.Contains("TEST private order result",StringComparison.Ordinal));Assert.Contains(saved.Messages,m=>m.Text=="Đã gửi thông tin riêng đã xác minh qua kênh.");
        var dispatch=s.TakeChannelDispatch(c);Assert.NotNull(dispatch);Assert.Equal("private",dispatch!.Kind);Assert.Equal("TEST private order result",dispatch.Text);Assert.Equal(generation,dispatch.IdentityGeneration);Assert.Null(s.ChannelDispatchBlock(c,dispatch));
        s.RevokeIdentity(1,row.VisitorId,id,Guid.NewGuid());Assert.Equal("customer_identity_changed",s.ChannelDispatchBlock(c,dispatch));
    }
    [Fact]public void Zalo_identity_is_bound_to_one_sender_profile_peer_and_customer_generation(){
        var s=Store();var c=Zalo();var id=Import(s,c,Input("zalo-initial",peer:"peer-1",text:"Xin chào"));var row=s.StaffGet(agent,id);row=s.StaffCommand(agent,id,new(Guid.NewGuid(),"claim",row.Version));
        var issue=new CustomerIdentityIssue(Guid.NewGuid(),row.Version,42,"in_person","TEST verified in person",true);var code=s.IssueIdentity(agent,id,issue,Protector,"PROTECTED_TEST_PHONE");
        Assert.Throws<AssistantException>(()=>s.RequireChannelIdentityTarget(c,1,Guid.NewGuid(),id));Assert.False(s.RedeemIdentity(1,row.VisitorId,id,new(Guid.NewGuid(),"WRONG")));
        Assert.True(s.RedeemIdentity(1,row.VisitorId,id,new(Guid.NewGuid(),code.Code!)));var target=s.RequireChannelIdentityTarget(c,1,row.VisitorId,id);var generation=s.ActiveChannelIdentityGeneration(c,id,target);Assert.NotNull(generation);
        Assert.Null(s.ActiveChannelIdentityGeneration(Zalo("zalo-other-profile"),id,target));s.InvalidateChannelIdentity(c,id,"peer-1",generation!.Value);Assert.Null(s.ActiveChannelIdentityGeneration(c,id,target));
    }
    [Theory][InlineData("needs-human")][InlineData("older")][InlineData("long")][InlineData("attachment")][InlineData("explicit-handoff")]
    public void Unsafe_private_zalo_messages_never_enter_the_private_read_queue(string condition){
        var s=Store();var c=Zalo(ai:false);var id=Import(s,c,Input("zalo-initial",peer:"peer-1",text:"Xin chào"));ReadyZalo(s,c);c.AutoReply=true;
        var incoming=Input("zalo-unsafe-"+condition,peer:"peer-1",text:"đơn hàng của tôi");
        incoming=condition switch {
            "needs-human"=>incoming with{NeedsHuman=true},
            "older"=>incoming with{SentAt=clock.Now.AddMinutes(-1)},
            "long"=>incoming with{Text="đơn hàng của tôi "+new string('x',2100)},
            "attachment"=>incoming with{Zalo=new CustomerZaloMessage(2,"File",null,null,[new CustomerZaloAttachment(Guid.NewGuid(),"File","TEST.pdf","application/pdf",50)])},
            "explicit-handoff"=>incoming with{Text="đơn hàng của tôi, gặp nhân viên"},
            _=>throw new InvalidOperationException()
        };
        Assert.Equal(id,s.ImportChannel(c,incoming));Assert.Null(s.TakeChannelPrivateTurn(c));Assert.Null(s.TakeChannelTurn(c));Assert.Null(s.TakeChannelDispatch(c));
    }
    public void Dispose(){if(Directory.Exists(directory))Directory.Delete(directory,true);}
}
